    public static function key(string $source):string{return 'account_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array{$messages=[];$english=explode('-',$locale,2)[0]==='en';foreach(self::ENGLISH as $source=>$translation)$messages[self::key($source)]=$english?$translation:$source;return $messages;}
    /** Only declared fixed labels may be supplied to a widget, never account data. */
    public static function browser(array $messages,array $sources):array
    {
        $out=[];foreach($sources as $source){if(!is_string($source)||!isset(self::ENGLISH[$source]))throw new \InvalidArgumentException('Unbekannter Kontotext.');$out[$source]=$messages[self::key($source)]??$source;}return $out;
    }
    public static function text(string $source,?Catalog $catalog=null,string $locale='de'):string
    {
        if(!isset(self::ENGLISH[$source]))return $source;
        return $catalog?$catalog->text(self::key($source)):self::messages($locale)[self::key($source)];
    }
